    'RegisterSimpleRisk'=>'تسجيل SimpleRisk',
    'RegistrationText'=>'تُمنح نُسخ SimpleRisk المسجلة على الفور حق الوصول إلى إضافتي الترقية وإطار ضوابط الأمن الآمنة (SCF).  توفر إضافة الترقية إمكانية إنشاء نسخة احتياطية من نسخة SimpleRisk الخاصة بك وترقيتها بنقرة زر واحدة.  توفر إضافة إطار ضوابط الأمن الآمنة (SCF) إطار ضوابط مشتركًا مدمجًا في وظائف الحوكمة في SimpleRisk.  عند تسجيل SimpleRisk، سيتم إرسال معلومات التسجيل الخاصة بك إلى خادم تستضيفه SimpleRisk.  ستستخدم SimpleRisk معلومات التسجيل المقدمة لإبلاغ العملاء بالإصدارات الجديدة وتحديثات الأمن.  سيؤدي تسجيل SimpleRisk إلى اشتراكك في اتصالاتنا التسويقية، ولكن يمكنك إلغاء الاشتراك في أي وقت باستخدام رابط إلغاء الاشتراك الموجود في هذه الاتصالات.  تحترم SimpleRisk خصوصية عملائنا، ولن تُباع المعلومات المقدمة إلينا من خلال عملية تسجيل SimpleRisk إلى أي طرف ثالث أبدًا.',
