    'SettingsDesc'                        => 'قم بتهيئة الإعدادات على مستوى النظام: عنوان URL الأساسي، والأمن، واللغة الافتراضية، والمنطقة الزمنية، والقيم الافتراضية لتسجيل نقاط المخاطر، وغير ذلك.',
    'SettingsPreferencesDesc'             => 'القيم الافتراضية والتفضيلات السلوكية في SimpleRisk: اللغة، والمنطقة الزمنية، وحالات التدقيق، ومتطلبات ربط المخاطر، ومفاتيح تبديل سلوك واجهة المستخدم، وما شابه.',
