    'RegisterAndUpgradeDesc'              => 'قم بتسجيل تثبيت SimpleRisk الخاص بك، وأدخل مفتاح الاشتراك أو جدده، وقم بتشغيل ترقيات Core/Extra بنقرة واحدة.',
    'QueueMonitorDesc'                    => 'افحص قائمة انتظار المهام الخلفية: المهام المعلقة، والمهام قيد التنفيذ، والمهام الفاشلة.',
    'ExtrasDesc'                          => 'تنشيط إضافات SimpleRisk (Extras) وإلغاء تنشيطها وتهيئتها (وحدات إضافية مدفوعة).',
    'ArtificialIntelligenceExtraDesc'     => 'توفر إضافة الذكاء الاصطناعي (Artificial Intelligence Extra) تحليلًا محسّنًا للمخاطر (بما في ذلك تقييمات FAIR) ومستندات مخصصة.',
    'CustomizationExtraDesc'              => 'تتيح إضافة التخصيص (Customization Extra) إمكانية إضافة أنواع مختلفة من الحقول وإزالتها وإنشاء قوالب صفحات مخصصة بشكل ديناميكي.',
    'NotificationExtraDesc'               => 'تُمكّن إضافة إشعارات البريد الإلكتروني SimpleRisk من إرسال إشعارات عبر البريد الإلكتروني عند تقديم المخاطر أو تعديلها أو اتخاذ أي إجراء بشأنها. كما يُمكن إضافة هذه الإضافة كبرنامج نصي مُجدول لإرسال تذكيرات دورية عندما تكون المخاطر جاهزة للمراجعة الإدارية. في منتج SimpleRisk الأساسي، وبدون هذه الإضافة، لا يتم إرسال أي إشعارات خارج الأداة نفسها.',
    'VulnerabilityManagementExtraDesc'    => 'توفر إضافة إدارة الثغرات (Vulnerability Management Extra) للعملاء القدرة على دمج نسخة SimpleRisk الخاصة بهم مع Qualys أو Tenable.io أو Rapid7 Nexpose/InsightVM واستيراد بيانات الأصول والثغرات إلى SimpleRisk. ومن هناك، يمكنك تحديد المواقع التي تريد تغطيتها، وتحديد درجات الثغرات التي يجب استيرادها، وفرز الثغرات التي يتم تحويلها إلى مخاطر لتتبعها.',
    'IncidentManagementExtraDesc'         => 'تستند إضافة إدارة الحوادث (Incident Management Extra) إلى دليل NIST 800-61 للتعامل مع حوادث أمن الحاسوب، وتوفر إمكانات إدارة الحوادث من داخل نظام SimpleRisk.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'أعد تسمية مصطلحات SimpleRisk (المخاطر، الأصل، الإطار، وغيرها) عبر واجهة المستخدم.',
    'RiskConfigurationDesc'               => 'تهيئة قواعد تسجيل نقاط المخاطر: المستويات، والقابلية للمخاطر، وحدود SLA، وصيغ المخاطر الكلاسيكية / المساهمة.',
    'RiskAndThreatCatalogDesc'            => 'صيانة كتالوج قيم المخاطر والتهديدات المستخدمة في القوائم المنسدلة.',
    'AddAndRemoveValuesDesc'              => 'إدارة قيم القوائم المنسدلة لحقول المخاطر: الموقع، المصدر، الفئة، الفريق، التكنولوجيا، والمزيد.',
    'AssetValuationDesc'                  => 'قم بضبط مقياس تقييم الأصول وتجاوزات تقييم كل أصل على حدة.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'إضافة المستخدمين وتعديلهم وتعطيلهم وإعادة تعيينهم؛ إدارة سياسة كلمات المرور.',
    'RoleManagementDesc'                  => 'تحديد الأدوار والأذونات التي يمنحها كل دور.',
    'TeamManagementDesc'                  => 'إنشاء وإدارة الفرق المستخدمة لتصفية رؤية السجلات.',
    'SeparationExtraDesc'                 => 'تُقيّد ميزة "الفصل القائم على الفريق" الإضافية عرض المخاطر للمستخدمين الأعضاء في الفريق المُخصّص له هذا الخطر فقط. أما في منتج SimpleRisk Core، فبدون هذه الميزة الإضافية، يُمكن لكل مستخدم رؤية جميع المخاطر.',
    'CustomAuthenticationExtraDesc'       => 'توفر إضافة المصادقة المخصصة دعمًا لمصادقة Active Directory وSAML. في منتج SimpleRisk الأساسي، وبدون هذه الإضافة، يكون الخيار الوحيد هو إنشاء مستخدمين جدد في مستودع هوية SimpleRisk.',
    'EncryptionExtraDesc'                 => 'تنشئ إضافة قاعدة البيانات المشفرة (Encrypted Database Extra) مفتاح تشفير AES-256 بت عشوائيًا ثم تستخدمه لتشفير النصوص الحساسة قبل إدراجها في قاعدة بيانات SimpleRisk. وهذا يمنع أي شخص من عرض البيانات أو تعديلها دون استخدام تطبيق SimpleRisk مباشرة.',
    'OrganizationManagementDesc'          => 'تتيح إضافة التسلسل الهرمي التنظيمي (Organizational Hierarchy Extra) إمكانية تحديد عدة وحدات أعمال يمكن أن تضم أي عدد من الفرق. ويمكن بعد ذلك تعيين المستخدمين عبر فريق واحد أو أكثر ضمن وحدات أعمال مختلفة. ويؤثر ذلك في قدرة المستخدم على رؤية الفرق والمستخدمين والأصول غير المرتبط بها واستخدامها.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'حذف المخاطر بشكل جماعي. استخدمه بحذر - عمليات الحذف دائمة.',
    'AuditTrailDesc'                      => 'ابحث في سجل تدقيق النظام الخاص بإجراءات المستخدم وقم بتصديره.',
    'ImportExportExtraDesc'               => 'تتيح ميزة الاستيراد والتصدير الإضافية إمكانية استيراد البيانات إلى SimpleRisk عن طريق ربط الحقول في ملف CSV بالحقول في قاعدة بيانات SimpleRisk. ويمكن استخدامها لاستيراد نتائج التدقيق من جداول بيانات خارجية، ونتائج فحص الثغرات الأمنية من أدوات أخرى، والأصول من قاعدة بيانات إدارة التكوين (CMDB)، وغير ذلك. كما تتيح هذه الميزة الإضافية إمكانية تصدير ملفات CSV من SimpleRisk تحتوي على المخاطر، وإجراءات التخفيف، والمراجعات، أو تقرير مُجمّع يجمع بين هذه العناصر الثلاثة.',
    'JiraExtraDesc'                       => 'تتيح إضافة Jira Integration Extra للمستخدمين إمكانية التكامل ثنائي الاتجاه مع نظام Jira. فهي تمكّن من ربط المخاطر بمشكلات Jira، بالإضافة إلى مزامنة بياناتها وحالتها وتعليقاتها.',
    'APIExtraDesc'                        => 'تتيح إضافة API (API Extra) للعملاء استخدام واجهة API من نوع RESTful لإنشاء تفاعلات مبرمجة مع التطبيقات الأخرى للحصول على أتمتة متقدمة والاستفادة من البنية التحتية الموجودة.',
    'AdvancedSearchExtraDesc'             => 'تحوّل إضافة البحث المتقدم (Advanced Search Extra) مربع البحث في الشريط العلوي إلى بحث واحد عبر المخاطر والأطر والضوابط والمستندات والاستثناءات والاختبارات وعمليات التدقيق والأصول ومجموعات الأصول، مع صفحة بحث كاملة للعمل على النتائج. ولا تعرض سوى السجلات المسموح للمستخدم برؤيتها.',
    'AssessmentsExtraDesc'                => 'توفر إضافة تقييم المخاطر (Risk Assessment Extra) للمستخدمين القدرة على تحديد جهات الاتصال، وإنشاء الأسئلة (بما في ذلك المنطق)، وتجميع عدة أسئلة في قالب استبيان، وإنشاء الاستبيانات وإرسالها إلى جهات الاتصال، وعرض نتائج الاستبيانات، وإضافة مخاطر بناءً على تلك النتائج، ومقارنة النتائج بمرور الوقت، واستيراد التقييمات المخصصة خارجيًا وتصديرها، ومراجعة سجل تدقيق تقييم المخاطر.',
    'ActiveAssessmentsDesc'               => 'عرض وإدارة التقييمات الجارية حاليًا.',
    'WorkflowsExtraDesc'                  => 'توفر إضافة Workflows Extra محرك سير عمل مرئيًا قائمًا على الأحداث، يعمل على أتمتة إجراءات إدارة المخاطر استجابةً للأحداث داخل SimpleRisk. يمكنك تصميم سير عمل يتم تفعيله عند حدوث تغييرات - مثل تقديم المخاطر أو تحديثها أو مراجعتها - لتوجيه الموافقات، وتوزيع المهام، والحفاظ على سير العملية بسلاسة دون تدخل يدوي.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'إضافة إطار ضوابط الأمان (SCF) Extra هي تكامل مباشر بين إطار ضوابط الأمان (Secure Controls Framework) وSimpleRisk. تستورد كتالوج الضوابط الخاص بـ SCF وتعيينات ربطها عبر مجموعة واسعة من أطر الامتثال والأمن السيبراني إلى وظائف الحوكمة في SimpleRisk، بحيث يمكنك اعتماد الأطر التي تحتاجها وإدارة ضوابطها دون بنائها يدويًا.',

