    'ControlIdOrShortNameFieldRequired' => 'يجب ربط حقل معرّف الضابط أو حقل الاسم المختصر للضابط -- لا يمكن تحديد هوية الصف بدون أحدهما.',
    'RiskImportSubjectNull' => 'معرف المخاطر {$risk_id}: لم يتم تحديثه لأن حقل الموضوع فارغ أو مفقود.',
