    'EncryptionPipelineStalledTask' => 'يبدو أن مسار التشفير (المهمة رقم {$id}، {$type}) متوقف — فهو في حالة {$status} منذ وقت طويل بشكل غير معتاد دون تقدم. يعني هذا عادةً أن عامل قائمة الانتظار في الخلفية غير قيد التشغيل؛ تحقق من أنه مجدول، ثم حاول مرة أخرى بعد أن يعالج المهمة المتوقفة.',
    'EncryptionPipelineStalledState' => 'يبدو أن مسار التشفير متوقف — فقد تم وضع علامة عليه قيد التنفيذ منذ وقت طويل بشكل غير معتاد دون وجود مهمة خلفية مطابقة يمكن الإشارة إليها. يعني هذا عادةً أن عامل قائمة الانتظار غير قيد التشغيل، أو أن مسارًا سابقًا انتهى دون تحديث هذه الحالة بشكل صحيح. تحقق من سجل التصحيح قبل المحاولة مرة أخرى.',
