    'UpgradeCorrectionUnknownVersionGuidance' => 'اضبط إعدادات db_version على الإصدار الذي يطابق مخطط قاعدة البيانات هذه فعليًا، ثم شغّل الترقية مرة أخرى: UPDATE settings SET value=\'<release>\' WHERE name=\'db_version\'. إذا كانت القيمة عنصرًا نائبًا مثل 2026XXXX-001، فإن القيمة الصحيحة هي في الغالب أحدث إصدار حقيقي تم تثبيته قبل تشغيل الترقية.',
