    'BaseScoreImpactMetrics' => 'مقاييس تأثير النتيجة الأساسية',
    // Per-field help popovers on the CVSS holder's 14 metric selects
    // (buildCvssScoreItem(), risk-details-form.js) -- one per CVSS v2
    // metric, matching the standard CVSS v2 specification definitions.
    // Double-quoted (not single-quoted, this file's usual style) so the
    // \n line breaks are real escape sequences: each popover leads with one
    // overall sentence, then one bullet line per option, rendered via
    // white-space: pre-line on .sr-scoring-help-popover .popover-body
    // (scss/modules/_questionnaire.scss) -- plain text throughout, no HTML,
    // so the popover stays initialized without Bootstrap's `html: true`.
    "AttackVectorHelp" => 'كيفية الوصول إلى الثغرة الأمنية.
• محلي: يتطلب وصولًا محليًا، مثل وحدة التحكم أو واجهة الأوامر.
• شبكة مجاورة: يجب أن يكون المهاجم ضمن مقطع الشبكة المادي أو المنطقي نفسه.
• الشبكة: يمكن استغلالها عن بُعد عبر الشبكة، دون الحاجة إلى وصول محلي أو مجاور.',
    "AttackComplexityHelp" => "مدى تعقيد الهجوم بمجرد حصول المهاجم على إمكانية الوصول إلى الهدف.\n• عالي: يتطلب شروطًا خاصة يصعب تحقيقها.\n• متوسط: يجب استيفاء بعض الشروط، ولكن الاستغلال ليس صعبًا بمجرد استيفائها.\n• منخفض: لا حاجة لشروط خاصة.",
    "AuthenticationHelp" => 'عدد المرات التي يجب على المهاجم فيها المصادقة على الهدف لاستغلاله.
• متعدد: تُطلب المصادقة مرتين أو أكثر، حتى مع بيانات الاعتماد نفسها.
• مفرد: تُطلب المصادقة مرة واحدة.
• لا يوجد: لا تُطلب أي مصادقة.',
    "ConfidentialityImpactHelp" => 'التأثير على سرية البيانات التي يعالجها النظام في حال الاستغلال.
• لا يوجد: لا تأثير.
• جزئي: إفصاح عن بعض المعلومات، لكن المهاجم لا يتحكم في ماهيتها، أو أن الفقد محدود.
• كامل: إفصاح كامل عن جميع المعلومات الموجودة على النظام.',
    "IntegrityImpactHelp" => 'التأثير على سلامة النظام في حال الاستغلال.
• لا يوجد: لا تأثير.
• جزئي: يمكن تعديل بعض البيانات، لكن المهاجم لا يتحكم في ماهيتها، أو أن النطاق محدود.
• كامل: اختراق تام لسلامة النظام؛ يمكن للمهاجم تعديل أي ملفات.',
    "AvailabilityImpactHelp" => "تأثير الاستغلال على توافر النظام.\n• لا يوجد: لا يوجد تأثير.\n• جزئي: انخفاض في الأداء أو انقطاعات في التوافر.\n• كامل: إيقاف تشغيل كامل للمورد المتأثر.",
    "RemediationLevelHelp" => 'مستوى المعالجة المتاح للثغرة الأمنية.
• إصلاح رسمي: يتوفر حل كامل من المورّد.
• إصلاح مؤقت: يتوفر إصلاح رسمي لكنه مؤقت.
• حل بديل: يوجد حل بديل غير رسمي من غير المورّد.
• غير متاح: لا يتوفر حل، أو لا يمكن تطبيق أي حل.',
    "ReportConfidenceHelp" => 'درجة الثقة في وجود الثغرة الأمنية ومصداقية تفاصيلها التقنية.
• غير مؤكد: تقرير واحد من مصدر غير مؤكد؛ والمشكلة الأساسية افتراضية.
• غير مدعوم: عدة مصادر مستقلة تبلغ عن السلوك نفسه، لكن السبب الجذري غير مؤكد.
• مؤكد: أقرّ المورّد بالمشكلة، أو تم تأكيدها عبر تحليل الشيفرة المصدرية أو الاستغلال.',
    "CollateralDamagePotentialHelp" => 'احتمال فقدان الأرواح أو الأصول المادية أو الخسارة المالية في حال استغلال الثغرة الأمنية.
• لا يوجد: لا يُرجَّح حدوث مثل هذه الخسارة.
• منخفض إلى متوسط: من الممكن حدوث خسارة متوسطة.
• عالي: تأثير كارثي على أصول المؤسسة أو إيراداتها أو سلامتها.',
    "TargetDistributionHelp" => 'نسبة الأنظمة المعرضة للثغرة في بيئتك.
• لا يوجد: لا توجد أنظمة مستهدفة.
• منخفض: 1-25% من الأنظمة معرضة للثغرة.
• متوسط: 26-75% معرضة للثغرة.
• عالي: 76-100% معرضة للثغرة.',
    "ConfidentialityRequirementHelp" => 'مدى أهمية سرية الأصل المتأثر بالنسبة لمؤسستك.
• منخفض: فقدان السرية له تأثير محدود.
• متوسط: له تأثير خطير.
• عالي: له تأثير كارثي.',
    "IntegrityRequirementHelp" => 'مدى أهمية سلامة الأصل المتأثر بالنسبة لمؤسستك.
• منخفض: فقدان السلامة له تأثير محدود.
• متوسط: له تأثير خطير.
• عالي: له تأثير كارثي.',
    "AvailabilityRequirementHelp" => 'مدى أهمية توافر الأصل المتأثر بالنسبة لمؤسستك.
• منخفض: فقدان التوافر له تأثير محدود.
• متوسط: له تأثير خطير.
• عالي: له تأثير كارثي.',
    // Base Score Metrics' two sub-group intro sentences (metricsSubGroup()'s
    // `descKey`, risk-details-form.js) -- orient the user to what the GROUP
    // as a whole is asking, distinct from the per-field *Help popover keys
    // above which explain each metric's own options.
    'BaseScoreExploitabilityMetricsDescription' => 'كيف يحتاج المهاجم إلى الوصول إلى هذه الثغرة وتفعيلها: أين يجب أن يكون، ومدى تعقيد الهجوم، وهل يحتاج إلى المصادقة أولاً.',
    'BaseScoreImpactMetricsDescription' => 'ماذا يحدث إذا تم استغلال الثغرة الأمنية بنجاح: التأثير على سرية وسلامة وتوافر النظام المتأثر.',
    // Advanced Metrics' three optional sub-group intro sentences -- same
    // metricsSubGroup() `descKey` as the two Base Score groups above.
    'TemporalScoreMetricsDescription' => 'كيف يتغير التهديد الواقعي لهذه الثغرة الأمنية بمرور الوقت: الحالة الحالية لرمز الاستغلال، وما هي الحلول المتاحة، ومدى ثقة التقارير في وجودها.',
    'EnvironmentalScoreMetricsDescription' => 'كيف تعتمد مخاطر هذه الثغرة على بيئتك: احتمال حدوث ضرر فعلي، وعدد أنظمتك المتأثرة فعلياً.',
    'ImpactSubscoreModifiersDescription' => 'قم بترجيح تأثير الدرجة الأساسية بحسب مدى أهمية السرية والسلامة والتوافر فعلياً لهذا الأصل المحدد.',
    // Phase 4d-iii: DREAD holder help popovers (view_dread_help()'s
    // existing English text, includes/display.php, extracted to real $lang
    // keys -- that function's own content was raw hardcoded HTML, never
    // localized, so it could not be reused verbatim).
    'DamagePotentialHelp' => 'في حال حدوث استغلال للتهديدات، ما مقدار الضرر الذي سيحدث؟' . "\n" . '0 = لا شيء' . "\n" . '5 = تم اختراق بيانات المستخدم الفردية أو تأثرها.' . "\n" . '10 = تدمير النظام أو البيانات بالكامل',
    'ReproducibilityHelp' => 'ما مدى سهولة إعادة إنتاج استغلال التهديد؟
0 = صعب جدًا أو مستحيل، حتى بالنسبة لمسؤولي التطبيق.
5 = يتطلب خطوة أو خطوتين، وقد يلزم أن يكون مستخدمًا مخولًا.
10 = يكفي متصفح ويب وشريط العنوان، دون مصادقة.',
    'ExploitabilityHelp' => 'ما الذي يلزم لاستغلال هذا التهديد؟' . "\n" . '0 = معرفة متقدمة في البرمجة والشبكات، مع أدوات هجوم مخصصة أو متقدمة.' . "\n" . '5 = البرامج الضارة موجودة على الإنترنت، أو يمكن تنفيذ عملية استغلال بسهولة باستخدام أدوات الهجوم المتاحة.' . "\n" . '10 = مجرد متصفح ويب',
    'AffectedUsersHelp' => 'كم عدد المستخدمين الذين سيتأثرون؟
0 = لا أحد
5 = بعض المستخدمين وليس جميعهم
10 = جميع المستخدمين',
    'DiscoverabilityHelp' => 'ما مدى سهولة اكتشاف هذا التهديد؟
0 = صعب جدًا إلى مستحيل؛ يتطلب الشيفرة المصدرية أو وصولًا إداريًا.
5 = يمكن اكتشافه بالتخمين أو بمراقبة آثار الشبكة.
9 = تفاصيل مثل هذه الأخطاء متاحة بالفعل للعامة ويمكن اكتشافها بسهولة باستخدام محرك بحث.
10 = المعلومات ظاهرة في شريط عنوان متصفح الويب أو في نموذج.',
    // The DREAD holder's summary card heading and "DREAD Metrics" card
