    'ControlIdHeaderIsLegacy' => 'لم يتم استيراد أي شيء. عنوان العمود المرتبط بـ "معرّف الضابط (كما هو معروض)" هو "معرّف الضابط"، وهي الطريقة التي تسمّي بها الضوابط المصدّرة من إصدار سابق معرّفات قاعدة البيانات الخاصة بها. اربط ذلك العمود بـ "معرّف الضابط (معرّف قاعدة البيانات، تصدير قديم)" بدلاً من ذلك، أو قم بتصدير الضوابط مرة أخرى للحصول على المعرّفات المعروضة. إذا كان العمود يحتوي على معرّفات 1001 أو أكثر، فهو عمود معرّفات معروضة: أعد تسمية عنوانه إلى "معرّف الضابط (كما هو معروض)" ثم اربطه مرة أخرى.',
